/*
 * This file defines a series of Gulp tasks for project automation within this repository.
 * It includes tasks for code coverage measurement, JavaScript linting, unit testing, and
 * cleaning up generated files.
 *
 * All automation tasks are orchestrated using the 'gulp' module.
 */

'use strict' ; // Enforce strict mode for cleaner and safer JavaScript code execution.


// --- Module Imports and Core Configuration Variables ---
var gulp = require ( 'gulp' ) ,                               // The main Gulp build system.
    $ = require ( 'gulp-load-plugins' ) ( ) ,                 // Dynamically loads Gulp plugins.
    del = require ( 'del' ) ,                                 // A utility for deleting files and folders.
    lib = [                                                   // Defines the set of source files for linting and coverage.
        '**/*.js' ,                                           // All JavaScript files.
        '!test/**/*' ,                                        // Exclude any files within the 'test' directory.
        '!node_modules/**/*' ,                                // Exclude all files within the 'node_modules' directory.
        '!coverage/**/*'                                      // Exclude any files generated by code coverage reports.
    ] ;                                                       // End of variable declarations.


/**
 * Gulp task: 'coverage'
 * Instruments the source files for code coverage analysis.
 * This task depends on 'clean' to ensure a fresh instrumentation state.
 *
 * @returns {Stream} A Gulp stream for instrumenting files.
 */
gulp . task ( 'coverage' , [ 'clean' ] , function ( ) {
    return gulp . src ( lib )                                 // Select all JavaScript source files as defined in 'lib'.
        . pipe ( $ . istanbul ( ) )                           // Instrument these files using the Istanbul plugin.
        . pipe ( $ . istanbul . hookRequire ( ) ) ;           // Hook into Node.js's 'require' mechanism for coverage.
} ) ;


/**
 * Gulp task: 'jshint'
 * Runs JSHint on the defined source files to enforce code style and quality.
 *
 * @returns {Stream} A Gulp stream that processes files through JSHint.
 */
gulp . task ( 'jshint' , function ( ) {
    return gulp . src ( lib )                                 // Grab the source files for linting.
        . pipe ( $ . jshint ( ) )                             // Execute JSHint on the files.
        . pipe ( $ . jshint . reporter ( 'jshint-stylish' ) ) // Use the 'jshint-stylish' reporter for readable output.
        . pipe ( $ . jshint . reporter ( 'fail' ) ) ;         // Cause the Gulp task to fail if any JSHint errors are found.
} ) ;


/**
 * Helper function: mochaStream
 * Creates a Gulp stream for running Mocha tests. This function is
 * designed for reuse across different Mocha-related Gulp tasks.
 *
 * @returns {Stream} A Gulp stream configured to run Mocha tests.
 */
function mochaStream ( ) {
    // Select all test files ending with '_test.js' within the 'test' directory.
    // 'read: false' prevents Gulp from reading file contents into memory, optimizing for testing.
    return gulp . src ( 'test/*_test.js' , { read : false } )
        . pipe ( $ . mocha ( {
            reporter : 'spec'                                 // Use the 'spec' reporter for clear, descriptive test output.
        } ) ) ;
}


/**
 * Gulp task: 'mocha'
 * Runs Mocha unit tests and generates code coverage reports.
 * This task relies on the 'coverage' task to ensure proper instrumentation before tests run.
 *
 * @returns {Stream} A Gulp stream that executes tests and writes coverage reports.
 */
gulp . task ( 'mocha' , [ 'coverage' ] , function ( ) {
    return mochaStream ( )                                    // Execute the Mocha test stream.
        . pipe ( $ . istanbul . writeReports ( ) ) ;          // Write out the collected Istanbul code coverage reports.
} ) ;


/**
 * Gulp task: 'mocha:nocov'
 * Runs Mocha unit tests without generating code coverage reports.
 * This can be useful for quicker test iterations during development when coverage is not immediately needed.
 *
 * @returns {Stream} A Gulp stream that executes Mocha tests.
 */
gulp . task ( 'mocha:nocov' , function ( ) {
    return mochaStream ( ) ;                                  // Simply execute the Mocha test stream without coverage.
} ) ;


/**
 * Gulp task: 'clean'
 * Deletes specified files and directories to ensure a clean build environment.
 * This task uses the 'del' module for robust file deletion.
 */
gulp . task ( 'clean' , del . bind ( null , [ 'test/css' , 'coverage/**/*' ] ) ) ;


/**
 * Gulp task: 'default'
 * The default task that runs when 'gulp' is executed without specifying a task name.
 * It executes 'mocha' (which includes coverage) and 'jshint' tasks sequentially.
 */
gulp . task ( 'default' , [ 'mocha' , 'jshint' ] ) ;